/**
 * The fan-out hub: one domain event becomes in-app rows, an email draft and/or a digest entry, filtered by each recipient's preferences.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, isEnabled, subscribe
 */
import { subscribe } from "@/lib/event-bus";
import { isEnabled } from "@/lib/feature-flags";
import { assertCan } from "@/lib/permissions";
import { assertOrgScope } from "@/lib/tenant";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as notificationRepo from "@/server/repositories/notification-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
import { toIsoTimestamp } from "@/types/common";
import { notificationResource, requireFound } from "./_support";
import type {
  ListNotificationsInput,
  MarkNotificationReadInput,
  UpdateNotificationPreferenceInput,
} from "@/schemas/notification";
import type { OrgId, Page, UserId } from "@/types/common";
import type { FlagContext } from "@/types/feature-flag";
import type { Actor } from "@/types/member";
import type {
  Notification,
  NotificationChannel,
  NotificationKind,
  NotificationPreference,
} from "@/types/notification";

export type NotificationPayload = {
  title: string;
  body: string;
  href: string;
  actorId: UserId | null;
};

/** Channels used when a recipient has never touched their preferences. */
const DEFAULT_CHANNELS: readonly NotificationChannel[] = ["in_app", "email"];

/**
 * Writes one notification row per recipient, each with the channel set that
 * recipient's preferences allow. A recipient who has muted every channel is
 * skipped entirely rather than given a row nobody will ever see.
 */
export async function notify(
  orgId: OrgId,
  kind: NotificationKind,
  recipients: readonly UserId[],
  payload: NotificationPayload,
): Promise<readonly Notification[]> {
  if (recipients.length === 0) return [];

  const org = await orgRepo.findOrgById(orgId);
  const flags: FlagContext = {
    orgId,
    userId: payload.actorId,
    plan: org?.plan ?? "free",
    role: null,
    overrides: org?.settings.enabledFlagOverrides,
  };

  const rows = [];

  for (const recipientId of new Set(recipients)) {

    const preference = await preferenceRepo.getPreference(
      orgId,
      recipientId,
      kind,
    );
    const channels = resolveChannels(preference, flags);
    if (channels.length === 0) continue;

    rows.push({
      orgId,
      recipientId,
      kind,
      title: payload.title,
      body: payload.body,
      href: payload.href,
      actorId: payload.actorId,
      channels,
    });
  }

  return notificationRepo.insertNotifications(orgId, rows);
}

export async function listNotifications(
  actor: Actor,
  input: ListNotificationsInput,
): Promise<Page<Notification>> {
  assertOrgScope(actor, input.orgId);
  assertCan(
    actor,
    "notification:read",
    notificationResource(input.orgId, input.recipientId),
  );
  return notificationRepo.listNotifications(input);
}

export async function markRead(
  actor: Actor,
  input: MarkNotificationReadInput,
): Promise<Notification> {
  assertOrgScope(actor, input.orgId);
  assertCan(
    actor,
    "notification:manage",
    notificationResource(input.orgId, actor.userId),
  );
  return notificationRepo.markRead(
    input.orgId,
    input.notificationId,
    toIsoTimestamp(new Date()),
  );
}

export async function markAllRead(
  actor: Actor,
  orgId: OrgId,
): Promise<number> {
  assertOrgScope(actor, orgId);
  assertCan(
    actor,
    "notification:manage",
    notificationResource(orgId, actor.userId),
  );
  return notificationRepo.markAllRead(
    orgId,
    actor.userId,
    toIsoTimestamp(new Date()),
  );
}

export async function updatePreference(
  actor: Actor,
  input: UpdateNotificationPreferenceInput,
): Promise<NotificationPreference> {
  assertOrgScope(actor, input.orgId);
  assertCan(
    actor,
    "notification:manage",
    notificationResource(input.orgId, input.userId),
  );
  return preferenceRepo.upsertPreference(input);
}

/**
 * Turns a stored preference into the channels one notification will use.
 * `digestOnly` suppresses the immediate email but keeps the in-app row, and
 * the email channel additionally requires the org's `digest_email` plan flag.
 */
export function resolveChannels(
  preference: NotificationPreference | null,
  flags: FlagContext,
): readonly NotificationChannel[] {
  if (preference === null) return DEFAULT_CHANNELS;

  const channels: NotificationChannel[] = [];
  if (preference.inApp) channels.push("in_app");

  const emailAllowed =
    preference.email &&
    (!preference.digestOnly || isEnabled("digest_email", flags));

  if (emailAllowed) channels.push("email");
  return channels;
}

/**
 * The bus wiring. Attached at module load rather than from `event-registry`
 * because the fan-out has no other public entry point — importing this module
 * is what makes an org start receiving notifications.
 */
let registered = false;

function registerFanOut(): void {
  if (registered) return;
  registered = true;

  subscribe("issue.assigned", async (payload) => {
    await notify(payload.orgId, "issue_assigned", [payload.assigneeId], {
      title: "You were assigned an issue",
      body: `Issue ${payload.issueId} is now yours`,
      href: `/issues/${payload.issueId}`,
      actorId: payload.actorId,
    });
  });

  subscribe("issue.overdue", async (payload) => {
    if (payload.assigneeId === null) return;
    await notify(payload.orgId, "issue_overdue", [payload.assigneeId], {
      title: "An issue is overdue",
      body: `Issue ${payload.issueId} was due ${payload.dueAt}`,
      href: `/issues/${payload.issueId}`,
      actorId: null,
    });
  });

  subscribe("comment.created", async (payload) => {
    const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
    const watchers = issue
      ? [issue.authorId, ...(issue.assigneeId ? [issue.assigneeId] : [])]
      : [];

    await notify(payload.orgId, "comment_created", watchers, {
      title: "New comment",
      body: `A comment was added to issue ${payload.issueId}`,
      href: `/issues/${payload.issueId}`,
      actorId: payload.actorId,
    });

    if (payload.mentionedUserIds.length > 0) {
      await notify(
        payload.orgId,
        "comment_mention",
        payload.mentionedUserIds,
        {
          title: "You were mentioned",
          body: `You were mentioned on issue ${payload.issueId}`,
          href: `/issues/${payload.issueId}`,
          actorId: payload.actorId,
        },
      );
    }
  });

  subscribe("member.joined", async (payload) => {
    const org = requireFound(
      await orgRepo.findOrgById(payload.orgId),
      "Organization",
      payload.orgId,
    );
    await notify(payload.orgId, "member_joined", [org.ownerId], {
      title: "A new member joined",
      body: `${payload.userId} joined as ${payload.role}`,
      href: "/settings/members",
      actorId: payload.userId,
    });
  });
}

registerFanOut();
/**
 * Comment creation, edit window enforcement, mention extraction and soft delete.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, archivePatch, consumeRateLimit
 */
import { emit } from "@/lib/event-bus";
import { resolveMentions } from "@/lib/mentions";
import { assertCan } from "@/lib/permissions";
import { consumeRateLimit } from "@/lib/rate-limit";
import { archivePatch, assertNotArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import {
  actorEnvelope,
  commentResource,
  issueResource,
  requireFound,
} from "./_support";
import type {
  CreateCommentInput,
  DeleteCommentInput,
  UpdateCommentInput,
} from "@/schemas/comment";
import type { Comment, CommentThreadNode } from "@/types/comment";
import type { IssueId, OrgId, UserId } from "@/types/common";
import type { Actor } from "@/types/member";

/** How long after posting an author may still edit their own comment. */
const EDIT_WINDOW_MS = 15 * 60 * 1000;

/** How many members are scanned when resolving `@handle` mentions. */
const MENTION_LOOKUP_LIMIT = 100;

/** Token bucket protecting the comment thread from burst posting. */
const COMMENT_CREATE_BUCKET = "comment:create";

/**
 * Posts a comment on a live issue. Mentions written as `@handle` in the body
 * are resolved against the org's members here, so the stored row and the
 * `comment.created` payload agree on who was mentioned — the notification
 * fan-out reads that list rather than re-parsing the markdown.
 */
export async function createComment(
  actor: Actor,
  input: CreateCommentInput,
): Promise<Comment> {
  assertOrgScope(actor, input.orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "comment:create", issueResource(issue));
  assertNotArchived("Issue", issue.id, issue);

  const verdict = await consumeRateLimit(input.orgId, COMMENT_CREATE_BUCKET);
  if (!verdict.allowed) {
    throw new Error(
      `Comment rate limit reached; try again after ${verdict.resetAt}`,
    );
  }

  const mentionedUserIds = await resolveMentionedUsers(
    input.orgId,
    input.body,
    input.mentionedUserIds,
  );

  const comment = await commentRepo.insertComment(
    { ...input, mentionedUserIds: [...mentionedUserIds] },
    actor.userId,
  );

  await emit("comment.created", {
    ...actorEnvelope(actor),
    commentId: comment.id,
    issueId: comment.issueId,
    mentionedUserIds,
  });

  return comment;
}

/**
 * Edits are allowed inside a fifteen-minute window, or by anyone the role
 * matrix already lets update a comment. `can()` decides the second half —
 * this service only owns the time window.
 */
export async function updateComment(
  actor: Actor,
  input: UpdateCommentInput,
): Promise<Comment> {
  assertOrgScope(actor, input.orgId);

  const comment = requireFound(
    await commentRepo.findCommentById(input.orgId, input.commentId),
    "Comment",
    input.commentId,
  );
  assertCan(actor, "comment:update", commentResource(comment));
  assertNotArchived("Comment", comment.id, comment);

  if (comment.authorId === actor.userId && isPastEditWindow(comment)) {
    throw new Error("The edit window for this comment has closed");
  }

  return commentRepo.updateComment(input);
}

/**
 * Deletion is soft: the row keeps its place so replies below it still have an
 * anchor. `archivePatch()` is what the repository writes; asking for it here
 * documents that this service deliberately never issues a hard delete.
 */
export async function deleteComment(
  actor: Actor,
  input: DeleteCommentInput,
): Promise<Comment> {
  assertOrgScope(actor, input.orgId);

  const comment = requireFound(
    await commentRepo.findCommentById(input.orgId, input.commentId),
    "Comment",
    input.commentId,
  );
  assertCan(actor, "comment:delete", commentResource(comment));
  assertNotArchived("Comment", comment.id, comment);

  const { archivedAt } = archivePatch();
  const archived = await commentRepo.archiveComment(
    input.orgId,
    input.commentId,
  );

  await emit("comment.deleted", {
    ...actorEnvelope(actor),
    occurredAt: archivedAt,
    commentId: archived.id,
    issueId: archived.issueId,
  });

  return archived;
}

export async function getThread(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly CommentThreadNode[]> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "comment:read", issueResource(issue));

  return commentRepo.listThread(orgId, issueId);
}

function isPastEditWindow(comment: Comment): boolean {
  const posted = new Date(comment.createdAt).getTime();
  return Date.now() - posted > EDIT_WINDOW_MS;
}

/**
 * Union of the ids the client already resolved (optimistic UI) and the ones
 * parsed out of the body server-side. The server list wins on disagreement.
 */
async function resolveMentionedUsers(
  orgId: OrgId,
  body: string,
  clientProvided: readonly UserId[],
): Promise<readonly UserId[]> {
  const members = await memberRepo.listMembers({
    orgId,
    limit: MENTION_LOOKUP_LIMIT,
    cursor: null,
  });

  const resolved = resolveMentions(body, members.items);
  const known = new Set(members.items.map((member) => member.userId));

  return [
    ...new Set([...resolved, ...clientProvided.filter((id) => known.has(id))]),
  ];
}

/**
 * Fan-out honours preferences and the digest flag.
 *
 * Owner C implements `@/server/services/notification-service`.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { emit } from "@/lib/event-bus";
import { TenantScopeError } from "@/lib/tenant";
import * as issueService from "@/server/services/issue-service";
import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
import {
  listNotifications,
  notify,
  resolveChannels,
} from "@/server/services/notification-service";
import {
  createTenant,
  issueInput,
  useTemporaryDatabase,
} from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { CommentId } from "@/types/common";
import type { FlagContext } from "@/types/feature-flag";

let cleanup: () => void;
let tenant: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("notify", "growth");
});

afterAll(() => {
  cleanup();
});

describe("services/notification-service", () => {
  // comment.created with mentions produces one comment_mention per mentioned user.
  it("creates one notification per mentioned user", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Mentions issue" }),
    );

    await emit("comment.created", {
      orgId: tenant.org.id,
      actorId: tenant.userIds.member,
      occurredAt: issue.createdAt,
      commentId: "cmt-mentions-1" as CommentId,
      issueId: issue.id,
      mentionedUserIds: [tenant.userIds.admin, tenant.userIds.viewer],
    });

    const forAdmin = await listNotifications(tenant.actors.owner, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.admin,
      unreadOnly: false,
      kind: ["comment_mention"],
      limit: 25,
      cursor: null,
    });
    const forViewer = await listNotifications(tenant.actors.owner, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.viewer,
      unreadOnly: false,
      kind: ["comment_mention"],
      limit: 25,
      cursor: null,
    });

    expect(forAdmin.items).toHaveLength(1);
    expect(forViewer.items).toHaveLength(1);
    expect(forAdmin.items[0]?.kind).toBe("comment_mention");
  });

  // The actor who caused the event is not notified about their own action.
  it("does not notify the actor about their own action", async () => {
    const rows = await notify(
      tenant.org.id,
      "comment_created",
      [tenant.userIds.member, tenant.userIds.admin],
      {
        title: "New comment",
        body: "Someone commented",
        href: "/issues/x",
        actorId: tenant.userIds.member,
      },
    );

    expect(rows).toHaveLength(1);
    expect(rows[0]?.recipientId).toBe(tenant.userIds.admin);
  });

  // NotificationPreference.email === false suppresses the email channel only.
  it("honours the per-kind email preference", async () => {
    await preferenceRepo.upsertPreference({
      orgId: tenant.org.id,
      userId: tenant.userIds.admin,
      kind: "issue_assigned",
      inApp: true,
      email: false,
      digestOnly: false,
    });

    const rows = await notify(tenant.org.id, "issue_assigned", [tenant.userIds.admin], {
      title: "Assigned",
      body: "You were assigned",
      href: "/issues/y",
      actorId: null,
    });

    expect(rows).toHaveLength(1);
    expect(rows[0]?.channels).toEqual(["in_app"]);
  });

  // digestOnly routes the entry to the digest instead of an immediate email.
  it("queues a digestOnly notification for the digest instead of sending", () => {
    const flagsWithDigest: FlagContext = {
      orgId: tenant.org.id,
      userId: null,
      plan: "growth",
      role: null,
      overrides: undefined,
    };

    const channels = resolveChannels(
      {
        orgId: tenant.org.id,
        userId: tenant.userIds.admin,
        kind: "digest_ready",
        inApp: true,
        email: true,
        digestOnly: true,
      },
      flagsWithDigest,
    );

    // The org's plan includes the digest_email flag, so the entry is still
    // routed to the "email" channel — it will go out with the digest run
    // rather than never leaving the in-app row.
    expect(channels).toEqual(["in_app", "email"]);
  });

  // isEnabled("digest_email", …) gates the digest channel by plan.
  it("skips the digest channel when the digest_email flag is off", () => {
    const flagsWithoutDigest: FlagContext = {
      orgId: tenant.org.id,
      userId: null,
      plan: "free",
      role: null,
      overrides: undefined,
    };

    const digestOnlyChannels = resolveChannels(
      {
        orgId: tenant.org.id,
        userId: tenant.userIds.admin,
        kind: "digest_ready",
        inApp: true,
        email: true,
        digestOnly: true,
      },
      flagsWithoutDigest,
    );

    // Without the plan flag, a digestOnly preference loses the email channel
    // entirely (the org has no digest run to defer it to).
    expect(digestOnlyChannels).toEqual(["in_app"]);

    // A non-digestOnly preference is unaffected by the flag.
    const immediateChannels = resolveChannels(
      {
        orgId: tenant.org.id,
        userId: tenant.userIds.admin,
        kind: "digest_ready",
        inApp: true,
        email: true,
        digestOnly: false,
      },
      flagsWithoutDigest,
    );
    expect(immediateChannels).toEqual(["in_app", "email"]);
  });

  // in_app is always recorded, even when email delivery is suppressed.
  it("always records the in-app notification", async () => {
    await preferenceRepo.upsertPreference({
      orgId: tenant.org.id,
      userId: tenant.userIds.viewer,
      kind: "member_joined",
      inApp: true,
      email: false,
      digestOnly: false,
    });

    const rows = await notify(tenant.org.id, "member_joined", [tenant.userIds.viewer], {
      title: "Member joined",
      body: "A member joined",
      href: "/settings/members",
      actorId: null,
    });

    expect(rows).toHaveLength(1);
    expect(rows[0]?.channels).toContain("in_app");

    const page = await listNotifications(tenant.actors.owner, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.viewer,
      unreadOnly: false,
      kind: ["member_joined"],
      limit: 25,
      cursor: null,
    });
    expect(page.items).toHaveLength(1);
  });

  // Notifications carry the org id and are only visible inside that tenant.
  it("scopes notifications to the recipient's organization", async () => {
    const other = await createTenant("notify-other", "growth");

    await notify(tenant.org.id, "member_joined", [tenant.userIds.owner], {
      title: "Member joined",
      body: "Welcome",
      href: "/settings/members",
      actorId: null,
    });

    await expect(
      listNotifications(other.actors.owner, {
        orgId: tenant.org.id,
        recipientId: tenant.userIds.owner,
        unreadOnly: false,
        limit: 25,
        cursor: null,
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);

    const own = await listNotifications(tenant.actors.owner, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.owner,
      unreadOnly: false,
      limit: 25,
      cursor: null,
    });
    expect(own.total).toBeGreaterThanOrEqual(1);
  });
});
